  if (aiming && p.currentWeapon !== 'fists') {
    ctx.fillStyle = '#caa27a';
    ctx.fillRect(4, 3, 9, 3);
    ctx.fillRect(4, -6, 9, 3);
    drawWeapon(ctx, p.currentWeapon);
  } else if (p.currentWeapon !== 'fists') {
    ctx.fillStyle = '#caa27a';
    ctx.fillRect(3, 5, 8, 3);
