      }
      for (let i = 0; i < 4; i++) {
        const c = createCar(avX[2] - 18, p.y - 130 + i * 110, -Math.PI / 2, i % 5, false);
        c.speed = 60; c.vx = 0; c.vy = -60;
        world.cars.push(c);
      }
      const c2 = createCar(avX[2] + 18, p.y - 60, Math.PI / 2, 1, false);
      c2.speed = 80; c2.vx = 0; c2.vy = 80;
